## 2. 개선된 예제 코드 (int 기반)

> *필요에 따라 `BigInteger` 를 그대로 유지해도 무방합니다. 여기서는 일반적인 정수 연산에 적합한 `int` 로 다시 작성했습니다.*

```java
package practice;

import java.util.Scanner;

/**
 * while 문과 Scanner.nextLine() 를 이용해
 * 예금(1), 출금(2), 잔고 조회(3), 종료(4) 기능을 구현한 예제
 */
public class BankAccount {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int balance = 0;               // 초기 잔고
        boolean keepRunning = true;   // 루프 종료 플래그

        while (keepRunning) {
            // ---------- 메뉴 출력 ----------
            System.out.println("-----------------------------");
            System.out.println("1. 예금 | 2. 출금 | 3. 잔고 | 4. 종료");
            System.out.println("-----------------------------");

            // ---------- 메뉴 선택 입력 ----------
            System.out.print("선택> ");
            String choice = scan.nextLine().trim(); // 공백 제거

            switch (choice) {
                case "1": // 예금
                    System.out.print("예금액> ");
                    int deposit = readPositiveInt(scan);
                    if (deposit >= 0) {
                        balance += deposit;
                        System.out.println("예금이 완료되었습니다. 현재 잔고: " + balance);
                    } else {
                        System.out.println("올바른 값을 입력하세요 (양수)");
                    }
                    break;

                case "2": // 출금
                    System.out.print("출금액> ");
                    int withdraw = readPositiveInt(scan);
                    if (withdraw >= 0 && withdraw <= balance) {
                        balance -= withdraw;
                        System.out.println("출금이 완료되었습니다. 현재 잔고: " + balance);
                    } else {
                        System.out.println("잔액이 부족하거나 잘못된 금액입니다.");
                    }
                    break;

                case "3": // 잔고 조회
                    System.out.println("잔고>" + balance);
                    break;

                case "4": // 종료
                    keepRunning = false;
                    break;

                default:
                    System.out.println("1, 2, 3, 4 중 하나만 선택해 주세요.");
            }

            // ---------- 루프 종료 전 메뉴 재출력 ----------
            System.out.println(); // 빈 줄
        }

        System.out.println("프로그램 종료");
        scan.close();
    }

    /**
     * Scanner에서 정수를 읽되, 음수나 비어있는 줄이 들어오면 -1 을 반환한다.
     */
    private static int readPositiveInt(Scanner scan) {
        String line = scan.nextLine().trim();
        if (line.isEmpty()) {
            return -1;
        }
        try {
            int value = Integer.parseInt(line);
            return value; // 양수·음수 모두 반환 → 호출부에서 검증
        } catch (NumberFormatException e) {
            return -1; // 파싱 실패 → -1
        }
    }
}
```

